document.addEventListener("DOMContentLoaded",()=>{document.addEventListener("input",e=>{const t=e.target;if("INPUT"===t.tagName&&"text"===t.type){if(t.hasAttribute("oninput")&&t.getAttribute("oninput").includes("formatarMoeda"))return;if((t.id.match(/peso|altura|taxa|tempo|percent|valor|medida|tamanho|quantidade/i)||t.placeholder.toLowerCase().includes("ex:"))&&t.value.includes(".")){const e=t.selectionStart,a=t.selectionEnd;t.value=t.value.replace(/\./g,","),t.setSelectionRange(e,a)}}})}),window.converterParaNumero=function(e){if(!e)return 0;if(e.includes(","))return parseFloat(e.replace(/\./g,"").replace(",","."));const t=e.split(".");return 2===t.length&&t[1].length<=2?parseFloat(e):parseFloat(e.replace(/\./g,""))};